#include <iostream>
#include <fstream>
#include <vector>
#include <map>
using namespace std;

bool czyPierwsza(int n) {
    if (n < 2) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    for (int i = 3; i * i <= n; i += 2)
        if (n % i == 0) return false;
    return true;
}

int wartoscCyfrowa(int n) {
    int suma = 0;
    while (n > 0) {
        int c = n % 10;
        suma += c * c;
        n /= 10;
    }
    return suma;
}

int main() {
    ifstream plik("dane.txt");
    vector<int> tab;
    int x;
    while (plik >> x) tab.push_back(x);

    vector<int> wc;
    cout << "a) Wartosci cyfrowe:" << endl;
    for (int n : tab) {
        int w = wartoscCyfrowa(n);
        wc.push_back(w);
        // Wypisz rozklad
        string s = to_string(n);
        cout << "   " << n << " -> ";
        for (int i = 0; i < s.length(); i++) {
            int c = s[i] - '0';
            if (i > 0) cout << "+";
            cout << c * c;
        }
        cout << " = " << w << endl;
    }

    cout << endl << "b) Liczby z pierwsza wartoscia cyfrowa:" << endl;
    int ileB = 0;
    for (int i = 0; i < tab.size(); i++) {
        if (czyPierwsza(wc[i])) {
            cout << "   " << tab[i] << " (wc=" << wc[i] << ")" << endl;
            ileB++;
        }
    }
    cout << "   Ilosc: " << ileB << endl;

    cout << endl << "c) Pierwsza para z ta sama wartoscia cyfrowa:" << endl;
    map<int, int> pierwsze;
    bool znaleziono = false;
    for (int i = 0; i < tab.size(); i++) {
        if (pierwsze.count(wc[i])) {
            int j = pierwsze[wc[i]];
            cout << "   " << tab[j] << " i " << tab[i]
                 << " (obie: wc=" << wc[i] << ")" << endl;
            znaleziono = true;
            break;
        }
        pierwsze[wc[i]] = i;
    }
    if (!znaleziono) cout << "   Brak par" << endl;
    return 0;
}
```

